import os
from typing import Any, Dict, Optional

import requests


class IBMAppIDTokenRefresher:
    def __init__(
        self,
        client_id: Optional[str] = None,
        client_secret: Optional[str] = None,
        appid_url: Optional[str] = None,
        session: Optional[requests.Session] = None,
    ) -> None:
        self.client_id = client_id or os.getenv("IBM_APPID_CLIENT_ID")
        self.client_secret = client_secret or os.getenv("IBM_APPID_CLIENT_SECRET")
        self.appid_url = (appid_url or os.getenv("IBM_APPID_URL") or "").rstrip("/")
        self.session = session or requests.Session()

        if not self.client_id or not self.client_secret:
            raise ValueError("IBM App ID client credentials are required.")
        if not self.appid_url:
            raise ValueError("IBM App ID base URL is required via IBM_APPID_URL.")

    def refresh_access_token(self, refresh_token: str) -> Dict[str, Any]:
        if not refresh_token:
            raise ValueError("refresh_token is required.")

        token_url = f"{self.appid_url}/oauth/v4/token"

        response = self.session.post(
            token_url,
            data={
                "grant_type": "refresh_token",
                "refresh_token": refresh_token,
            },
            auth=(self.client_id, self.client_secret),
            headers={
                "Accept": "application/json",
                "Content-Type": "application/x-www-form-urlencoded",
            },
            timeout=30,
        )
        response.raise_for_status()
        return response.json()

    def refresh_expired_session(self, refresh_token: str) -> Dict[str, Any]:
        token_data = self.refresh_access_token(refresh_token)
        return {
            "access_token": token_data.get("access_token"),
            "refresh_token": token_data.get("refresh_token", refresh_token),
            "id_token": token_data.get("id_token"),
            "token_type": token_data.get("token_type"),
            "expires_in": token_data.get("expires_in"),
            "raw": token_data,
        }


def refresh_expired_session(refresh_token: str, appid_url: Optional[str] = None) -> Dict[str, Any]:
    return IBMAppIDTokenRefresher(appid_url=appid_url).refresh_expired_session(refresh_token)
